class Solution {
    public int firstRepeat(int[] nums) {
        Map<Integer, Boolean> seen = new HashMap<>();
        for (int x : nums) {
            if (seen.containsKey(x)) return x;
            seen.put(x, true);
        }
        return -1;
    }
}

