import java.util.*;

class Solution {
    public int wordCount(String sentence, String target) {
        Map<String, Integer> count = new HashMap<>();
        for (String w : sentence.split(" ")) {
            count.put(w, count.getOrDefault(w, 0) + 1);
        }
        return count.getOrDefault(target, 0);
    }
}

