import java.util.*;

class Solution {
    public int[] byFrequency(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.put(x, count.getOrDefault(x, 0) + 1);
        List<Map.Entry<Integer, Integer>> entries = new ArrayList<>(count.entrySet());
        entries.sort((a, b) -> !a.getValue().equals(b.getValue())
                ? Integer.compare(b.getValue(), a.getValue())
                : Integer.compare(a.getKey(), b.getKey()));
        int[] res = new int[entries.size()];
        for (int i = 0; i < res.length; i++) res[i] = entries.get(i).getKey();
        return res;
    }
}

