import java.util.*;

class Solution {
    public int sumOfCounts(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.put(x, count.getOrDefault(x, 0) + 1);
        int sum = 0;
        for (int v : count.values()) sum += v;
        return sum;
    }
}
